import{_ as a,c as s,o,aj as t}from"./chunks/framework.Id7s26SP.js";const m=JSON.parse('{"title":"Interface: AgentSessionsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/AgentSessionsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/AgentSessionsAPI.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/AgentSessionsAPI.md"};function n(d,e,i,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[t('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / AgentSessionsAPI</p><h1 id="interface-agentsessionsapi" tabindex="-1">Interface: AgentSessionsAPI <a class="header-anchor" href="#interface-agentsessionsapi" aria-label="Permalink to “Interface: AgentSessionsAPI”">​</a></h1><p>Agent sessions, available as <code>client.agents.sessions</code>.</p><p>A session is created by a server function (<code>ctx.agents.createSession</code>); from a client you list the sessions you own or belong to, open one as a live view, send messages, upload and read their files, answer calls, record events, cancel a turn and mark a session read, and — as its owner — rename it, delete it and manage its members. App owners and admins may also list any user&#39;s sessions and get or delete any session. A refusal rejects with the client&#39;s ordinary request error carrying the server&#39;s <code>code</code> (for example <code>AGENT_SESSION_OWNER_ONLY</code> or <code>AGENT_SESSION_NOT_FOUND</code>).</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="inspect" tabindex="-1">inspect <a class="header-anchor" href="#inspect" aria-label="Permalink to “inspect”">​</a></h3><blockquote><p><code>readonly</code> <strong>inspect</strong>: <a href="./AgentSessionInspectAPI.html"><code>AgentSessionInspectAPI</code></a></p></blockquote><p>Diagnostics for a session: <code>inspect.storage(sessionId)</code>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="addmember" tabindex="-1">addMember() <a class="header-anchor" href="#addmember" aria-label="Permalink to “addMember()”">​</a></h3><blockquote><p><strong>addMember</strong>(<code>sessionId</code>, <code>userId</code>, <code>role</code>): <code>Promise</code>&lt;<a href="./AgentSessionMembersResult.html"><code>AgentSessionMembersResult</code></a>&gt;</p></blockquote><p>Add a member, or change an existing member&#39;s role (owner only). The user must be an existing user of this app; a session holds at most 50 members.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="userid" tabindex="-1">userId <a class="header-anchor" href="#userid" aria-label="Permalink to “userId”">​</a></h5><p><code>string</code></p><p>The user to add</p><h5 id="role" tabindex="-1">role <a class="header-anchor" href="#role" aria-label="Permalink to “role”">​</a></h5><p><a href="./../type-aliases/AgentSessionMemberRole.html"><code>AgentSessionMemberRole</code></a></p><p><code>viewer</code> or <code>participant</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionMembersResult.html"><code>AgentSessionMembersResult</code></a>&gt;</p><hr><h3 id="answer" tabindex="-1">answer() <a class="header-anchor" href="#answer" aria-label="Permalink to “answer()”">​</a></h3><blockquote><p><strong>answer</strong>(<code>sessionId</code>, <code>callId</code>, <code>answer</code>): <code>Promise</code>&lt;<a href="./AgentCallAnswerResult.html"><code>AgentCallAnswerResult</code></a>&gt;</p></blockquote><p>Answer a call the active turn waits on: approve or deny it, or give a client tool&#39;s output or error. The first valid answer wins.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-1" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-1" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="callid" tabindex="-1">callId <a class="header-anchor" href="#callid" aria-label="Permalink to “callId”">​</a></h5><p><code>string</code></p><p>The call, the tool call part&#39;s <code>toolCallId</code></p><h5 id="answer-1" tabindex="-1">answer <a class="header-anchor" href="#answer-1" aria-label="Permalink to “answer”">​</a></h5><p><a href="./../type-aliases/AgentCallAnswer.html"><code>AgentCallAnswer</code></a></p><p>Exactly one of <code>approval</code>, <code>output</code> or <code>error</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentCallAnswerResult.html"><code>AgentCallAnswerResult</code></a>&gt;</p><hr><h3 id="attachmentheaders" tabindex="-1">attachmentHeaders() <a class="header-anchor" href="#attachmentheaders" aria-label="Permalink to “attachmentHeaders()”">​</a></h3><blockquote><p><strong>attachmentHeaders</strong>(<code>sessionId</code>, <code>blobId</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./AgentSessionAttachmentHeaders.html"><code>AgentSessionAttachmentHeaders</code></a>&gt;</p></blockquote><p>Read a session file&#39;s download headers without its bytes. A refusal has no body, so it rejects with the error&#39;s <code>status</code> (404, 403, 410) and no <code>code</code>; call <code>get()</code> to tell a missing session from a missing file.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-2" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-2" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="blobid" tabindex="-1">blobId <a class="header-anchor" href="#blobid" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The file&#39;s id</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./AgentSessionAttachmentReadOptions.html"><code>AgentSessionAttachmentReadOptions</code></a></p><p>The disposition the headers describe</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionAttachmentHeaders.html"><code>AgentSessionAttachmentHeaders</code></a>&gt;</p><hr><h3 id="cancel" tabindex="-1">cancel() <a class="header-anchor" href="#cancel" aria-label="Permalink to “cancel()”">​</a></h3><blockquote><p><strong>cancel</strong>(<code>sessionId</code>, <code>turnId</code>): <code>Promise</code>&lt;<a href="./AgentSessionCancelResult.html"><code>AgentSessionCancelResult</code></a>&gt;</p></blockquote><p>Cancel the active turn, naming it; a turn that is no longer active is refused with <code>AGENT_TURN_STALE</code>. <code>open()</code>&#39;s view fills the turn in.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-3" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-3" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="turnid" tabindex="-1">turnId <a class="header-anchor" href="#turnid" aria-label="Permalink to “turnId”">​</a></h5><p><code>string</code></p><p>The active turn</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionCancelResult.html"><code>AgentSessionCancelResult</code></a>&gt;</p><hr><h3 id="delete" tabindex="-1">delete() <a class="header-anchor" href="#delete" aria-label="Permalink to “delete()”">​</a></h3><blockquote><p><strong>delete</strong>(<code>sessionId</code>): <code>Promise</code>&lt;<a href="./AgentSessionDeleteResult.html"><code>AgentSessionDeleteResult</code></a>&gt;</p></blockquote><p>Delete a session and its document (the owner, an app owner or an admin). Deleting a session that is already deleted succeeds again. Once it resolves, this client&#39;s queued uploads to the session, and the messages waiting on them, fail with <code>AGENT_SESSION_NOT_FOUND</code>.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-4" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-4" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionDeleteResult.html"><code>AgentSessionDeleteResult</code></a>&gt;</p><hr><h3 id="downloadattachment" tabindex="-1">downloadAttachment() <a class="header-anchor" href="#downloadattachment" aria-label="Permalink to “downloadAttachment()”">​</a></h3><blockquote><p><strong>downloadAttachment</strong>(<code>sessionId</code>, <code>blobId</code>, <code>options?</code>): <code>Promise</code>&lt;<code>ArrayBuffer</code>&gt;</p></blockquote><p>Download a session&#39;s file (members, the owner, app owners and admins). Rejects with the server&#39;s <code>code</code>: <code>AGENT_SESSION_ATTACHMENT_NOT_FOUND</code> for an id the session does not hold, <code>AGENT_SESSION_NOT_FOUND</code> without standing.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-5" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-5" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="blobid-1" tabindex="-1">blobId <a class="header-anchor" href="#blobid-1" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The file&#39;s id</p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./AgentSessionAttachmentReadOptions.html"><code>AgentSessionAttachmentReadOptions</code></a></p><p>The disposition to serve it with</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>ArrayBuffer</code>&gt;</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>sessionId</code>): <code>Promise</code>&lt;<a href="./AgentSessionInfo.html"><code>AgentSessionInfo</code></a>&gt;</p></blockquote><p>Get one session. Members, the owner, app owners and admins may; anyone else is answered <code>AGENT_SESSION_NOT_FOUND</code>. App owners and admins also receive <code>object</code> and <code>turnContexts</code>.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-6" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-6" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionInfo.html"><code>AgentSessionInfo</code></a>&gt;</p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>(<code>options?</code>): <code>Promise</code>&lt;<a href="./ListResult.html"><code>ListResult</code></a>&lt;<a href="./AgentSessionListItem.html"><code>AgentSessionListItem</code></a>&gt;&gt;</p></blockquote><p>List one user&#39;s sessions — your own by default — newest first. Pages may be shorter than <code>limit</code> when <code>scope</code> filters entries out; follow <code>nextCursor</code> while <code>hasMore</code> is true.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-2" tabindex="-1">options? <a class="header-anchor" href="#options-2" aria-label="Permalink to “options?”">​</a></h5><p><a href="./ListAgentSessionsOptions.html"><code>ListAgentSessionsOptions</code></a></p><p>Whose sessions, filters and paging</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./ListResult.html"><code>ListResult</code></a>&lt;<a href="./AgentSessionListItem.html"><code>AgentSessionListItem</code></a>&gt;&gt;</p><hr><h3 id="markread" tabindex="-1">markRead() <a class="header-anchor" href="#markread" aria-label="Permalink to “markRead()”">​</a></h3><blockquote><p><strong>markRead</strong>(<code>sessionId</code>): <code>Promise</code>&lt;<a href="./AgentSessionReadResult.html"><code>AgentSessionReadResult</code></a>&gt;</p></blockquote><p>Mark a session read for the signed-in user (the owner, a participant or a viewer): its <code>hasUnread</code> is false in <code>list()</code> and <code>get()</code>, on every device, until the next activity. Call it when the user opens the session; an open view&#39;s <code>markRead()</code> does the same and updates its <code>info</code>. An app owner or admin who is not in the session is refused with <code>AGENT_SESSION_MEMBER_ONLY</code>.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-7" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-7" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionReadResult.html"><code>AgentSessionReadResult</code></a>&gt;</p><hr><h3 id="open" tabindex="-1">open() <a class="header-anchor" href="#open" aria-label="Permalink to “open()”">​</a></h3><blockquote><p><strong>open</strong>(<code>sessionId</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./../classes/AgentSessionView.html"><code>AgentSessionView</code></a>&gt;</p></blockquote><p>Open a session as a live view: its info, the latest page of messages with their parts and steps (older pages with <code>loadOlder()</code>), your own messages shown at once while they send, and <code>onChange</code> on every change. <code>info</code> stays current as the session changes, and <code>attachments</code> uploads and reads the session&#39;s files. Opens the session&#39;s document through the client&#39;s internals; call <code>close()</code> when done. A refusal from <code>get()</code> rejects before anything is opened.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-8" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-8" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="options-3" tabindex="-1">options? <a class="header-anchor" href="#options-3" aria-label="Permalink to “options?”">​</a></h5><p><a href="./OpenAgentSessionOptions.html"><code>OpenAgentSessionOptions</code></a></p><p>Page size, model classes, document open options, and <code>markRead: &quot;while-open&quot;</code> to keep the session read while it is open</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../classes/AgentSessionView.html"><code>AgentSessionView</code></a>&gt;</p><hr><h3 id="recordevent" tabindex="-1">recordEvent() <a class="header-anchor" href="#recordevent" aria-label="Permalink to “recordEvent()”">​</a></h3><blockquote><p><strong>recordEvent</strong>(<code>sessionId</code>, <code>event</code>): <code>Promise</code>&lt;<a href="./AgentSessionEventResult.html"><code>AgentSessionEventResult</code></a>&gt;</p></blockquote><p>Record an event (the owner and participants): a message of one event part, read by the agent on its next turn. Never starts a turn.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-9" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-9" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="event" tabindex="-1">event <a class="header-anchor" href="#event" aria-label="Permalink to “event”">​</a></h5><p><a href="./AgentSessionEvent.html"><code>AgentSessionEvent</code></a></p><p>The kind, its data, and optional ids</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionEventResult.html"><code>AgentSessionEventResult</code></a>&gt;</p><hr><h3 id="removemember" tabindex="-1">removeMember() <a class="header-anchor" href="#removemember" aria-label="Permalink to “removeMember()”">​</a></h3><blockquote><p><strong>removeMember</strong>(<code>sessionId</code>, <code>userId</code>): <code>Promise</code>&lt;<a href="./AgentSessionMembersResult.html"><code>AgentSessionMembersResult</code></a>&gt;</p></blockquote><p>Remove a member (owner only): their grant on the document is revoked and the session leaves their list. Removing someone who is not a member succeeds with the members unchanged.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-10" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-10" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="userid-1" tabindex="-1">userId <a class="header-anchor" href="#userid-1" aria-label="Permalink to “userId”">​</a></h5><p><code>string</code></p><p>The member to remove</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionMembersResult.html"><code>AgentSessionMembersResult</code></a>&gt;</p><hr><h3 id="rename" tabindex="-1">rename() <a class="header-anchor" href="#rename" aria-label="Permalink to “rename()”">​</a></h3><blockquote><p><strong>rename</strong>(<code>sessionId</code>, <code>title</code>): <code>Promise</code>&lt;<a href="./AgentSessionRenameResult.html"><code>AgentSessionRenameResult</code></a>&gt;</p></blockquote><p>Rename a session (owner only). The title changes on the session, in every member&#39;s list, and on the document.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-11" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-11" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="title" tabindex="-1">title <a class="header-anchor" href="#title" aria-label="Permalink to “title”">​</a></h5><p><code>string</code></p><p>1 to 255 characters</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionRenameResult.html"><code>AgentSessionRenameResult</code></a>&gt;</p><hr><h3 id="send" tabindex="-1">send() <a class="header-anchor" href="#send" aria-label="Permalink to “send()”">​</a></h3><blockquote><p><strong>send</strong>(<code>sessionId</code>, <code>body</code>): <code>Promise</code>&lt;<a href="./AgentSessionSendResult.html"><code>AgentSessionSendResult</code></a>&gt;</p></blockquote><p>Send a message (the owner and participants). On an idle session it starts a turn; while a turn runs it waits in the queue. Refused with <code>AGENT_SESSION_PARTICIPANT_ONLY</code> for a viewer and <code>AGENT_SESSION_RATE_LIMITED</code> past the send limit.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-12" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-12" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="body" tabindex="-1">body <a class="header-anchor" href="#body" aria-label="Permalink to “body”">​</a></h5><p><a href="./AgentSessionSendBody.html"><code>AgentSessionSendBody</code></a></p><p>The text, files, your message id, and the turn context, time zone and locale</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionSendResult.html"><code>AgentSessionSendResult</code></a>&gt;</p><hr><h3 id="uploadattachment" tabindex="-1">uploadAttachment() <a class="header-anchor" href="#uploadattachment" aria-label="Permalink to “uploadAttachment()”">​</a></h3><blockquote><p><strong>uploadAttachment</strong>(<code>sessionId</code>, <code>blobId</code>, <code>upload</code>): <code>Promise</code>&lt;<a href="./AgentSessionAttachmentUploadResult.html"><code>AgentSessionAttachmentUploadResult</code></a>&gt;</p></blockquote><p>Upload a file to a session (the owner and participants), under a blob id you choose (a ULID), then send it with <code>send()</code> and <code>files: [{ blobId }]</code>. Uploading the same id with the same bytes again succeeds and transfers nothing; with other bytes it is refused. Rejects with the server&#39;s <code>code</code>: <code>AGENT_SESSION_PARTICIPANT_ONLY</code> for a viewer, <code>AGENT_SESSION_NOT_FOUND</code> without standing, <code>AGENT_SESSION_ATTACHMENT_NOT_FOUND</code> for an id another document holds.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sessionid-13" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid-13" aria-label="Permalink to “sessionId”">​</a></h5><p><code>string</code></p><p>The session</p><h5 id="blobid-2" tabindex="-1">blobId <a class="header-anchor" href="#blobid-2" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The file&#39;s id</p><h5 id="upload" tabindex="-1">upload <a class="header-anchor" href="#upload" aria-label="Permalink to “upload”">​</a></h5><p><a href="./AgentSessionAttachmentUpload.html"><code>AgentSessionAttachmentUpload</code></a></p><p>The bytes, the filename, and optionally the media type and disposition</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionAttachmentUploadResult.html"><code>AgentSessionAttachmentUploadResult</code></a>&gt;</p><hr><h3 id="watch" tabindex="-1">watch() <a class="header-anchor" href="#watch" aria-label="Permalink to “watch()”">​</a></h3><blockquote><p><strong>watch</strong>(<code>options?</code>): <code>Promise</code>&lt;<a href="./../classes/AgentSessionList.html"><code>AgentSessionList</code></a>&gt;</p></blockquote><p>Watch your sessions: the first page of <code>list()</code>, kept current as sessions change — new activity and the unread dot, read marks from your other devices, renames, status, members, removals and deletes — without opening any document. Items are ordered by last activity, newest first; <code>loadMore()</code> reads the next page, <code>onChange</code> hears every change, and the list reads its pages again after a reconnect. Call <code>close()</code> when done. Rejects as <code>list()</code> does; a <code>userId</code> option is a <code>TypeError</code>.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-4" tabindex="-1">options? <a class="header-anchor" href="#options-4" aria-label="Permalink to “options?”">​</a></h5><p><a href="./WatchAgentSessionsOptions.html"><code>WatchAgentSessionsOptions</code></a></p><p>Agent and scope filters, and the page size</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../classes/AgentSessionList.html"><code>AgentSessionList</code></a>&gt;</p>',218)])])}const b=a(r,[["render",n]]);export{m as __pageData,b as default};
